import{_ as e,o,c as n,a5 as c}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"02 — Xác thực, Phân quyền & Hồ sơ Người dùng / Khách hàng (Authentication, Authorization & Profiles)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/02-authentication-profile.md","filePath":"ba/02-authentication-profile.md"}'),d={name:"ba/02-authentication-profile.md"};function i(h,t,a,l,s,g){return o(),n("div",null,[...t[0]||(t[0]=[c('<h1 id="_02-—-xac-thuc-phan-quyen-ho-so-nguoi-dung-khach-hang-authentication-authorization-profiles" tabindex="-1">02 — Xác thực, Phân quyền &amp; Hồ sơ Người dùng / Khách hàng (Authentication, Authorization &amp; Profiles) <a class="header-anchor" href="#_02-—-xac-thuc-phan-quyen-ho-so-nguoi-dung-khach-hang-authentication-authorization-profiles" aria-label="Permalink to &quot;02 — Xác thực, Phân quyền &amp; Hồ sơ Người dùng / Khách hàng (Authentication, Authorization &amp; Profiles)&quot;">​</a></h1><p>&gt; Navigation: <a href="./README.html">← BA Overview &amp; Hub</a> · <a href="./01-organization-structure.html">← 01 - Organization Structure</a> · <a href="./03-agency-workspace.html">Tiếp: 03 - Agency &amp; Workspace →</a> &gt; &gt; <strong>Phạm vi FR chuẩn</strong> (đồng bộ 100% với <code>Các FR của hệ thống - Feature_Function Requirement.csv</code>): &gt; - <strong>Mục <code>3.2 Authentication &amp; Authorization</code></strong>: <strong>9 FR (<code>3.2.1</code> – <code>3.2.9</code>)</strong> | <code>UC-001</code> – <code>UC-009</code> | Đặc tả SRS: <a href="./../feature/srs/01-authentication/README.html">01-authentication</a> &gt; - <strong>Mục <code>3.3 User &amp; Client Profile</code></strong>: <strong>4 FR (<code>3.3.1</code> – <code>3.3.4</code>)</strong> | <code>UC-010</code> – <code>UC-013</code> | Đặc tả SRS: <a href="./../feature/srs/02-profile/README.html">02-profile</a> &gt; - Use Cases chi tiết: <a href="./use-cases/01-authentication-profile.html">use-cases/01-authentication-profile.md</a></p><hr><h2 id="_1-bang-tong-hop-yeu-cau-chuc-nang-chuan-3-2-3-3-—-13-frs" tabindex="-1">1. Bảng Tổng hợp Yêu cầu Chức năng Chuẩn (<code>3.2</code> &amp; <code>3.3</code> — 13 FRs) <a class="header-anchor" href="#_1-bang-tong-hop-yeu-cau-chuc-nang-chuan-3-2-3-3-—-13-frs" aria-label="Permalink to &quot;1. Bảng Tổng hợp Yêu cầu Chức năng Chuẩn (`3.2` &amp; `3.3` — 13 FRs)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Mã FR</th><th style="text-align:center;">Mã UC</th><th style="text-align:left;">Tên Chức năng Chuẩn (141-FR Baseline)</th><th style="text-align:left;">Actors / Roles Chuẩn</th><th style="text-align:left;">Mô tả Nghiệp vụ Cốt lõi</th></tr></thead><tbody><tr><td style="text-align:center;"><strong><code>3.2.1</code></strong></td><td style="text-align:center;"><code>UC-001</code></td><td style="text-align:left;"><strong>Sign Up</strong></td><td style="text-align:left;"><code>Guest</code></td><td style="text-align:left;">Đăng ký tài khoản mới bằng Họ tên, Email (chuẩn hóa chữ thường <code>BR-01</code>) và Mật khẩu (≥8 ký tự, ≥1 chữ số, băm bcrypt <code>BR-02</code>). Khởi tạo ở <code>PENDING_VERIFICATION</code>, sinh OTP 6 chữ số hiệu lực 10 phút (<code>BR-03</code>) chuyển sang <code>3.2.6</code>.</td></tr><tr><td style="text-align:center;"><strong><code>3.2.2</code></strong></td><td style="text-align:center;"><code>UC-002</code></td><td style="text-align:left;"><strong>Sign In with Email</strong></td><td style="text-align:left;"><code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></td><td style="text-align:left;">Đăng nhập trực tiếp bằng Email &amp; Mật khẩu trên <code>/login</code> (không gửi lại OTP mỗi lần đăng nhập trừ khi tài khoản bật 2FA TOTP ở <code>3.2.7</code>). Kiểm tra trạng thái hoạt động (<code>BR-05</code>) và cấp cặp RS256 Access Token (15 phút) + Refresh Token (30 ngày).</td></tr><tr><td style="text-align:center;"><strong><code>3.2.3</code></strong></td><td style="text-align:center;"><code>UC-003</code></td><td style="text-align:left;"><strong>Sign In with Google OAuth</strong></td><td style="text-align:left;"><code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></td><td style="text-align:left;">Đăng nhập hoặc đăng ký nhanh 1 chạm qua Google OAuth 2.0 (<code>/login</code>, <code>/register</code>). Xác thực Google ID Token &amp; cờ <code>email_verified</code>, tự động liên kết hoặc khởi tạo tài khoản <code>ACTIVE</code> (<code>BR-07</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.2.4</code></strong></td><td style="text-align:center;"><code>UC-004</code></td><td style="text-align:left;"><strong>Reset Password</strong></td><td style="text-align:left;"><code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></td><td style="text-align:left;">Khôi phục mật khẩu khi quên tại <code>/forgot-password</code>, <code>/reset-password</code> qua mã xác thực OTP 6 chữ số (hiệu lực 10 phút <code>BR-03</code>, tối đa 5 lần sai <code>BR-04</code>). Sau khi đặt mật khẩu mới hợp lệ (<code>BR-02</code>), thu hồi toàn bộ các phiên cũ (<code>BR-08</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.2.5</code></strong></td><td style="text-align:center;"><code>UC-005</code></td><td style="text-align:left;"><strong>Change Password</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></td><td style="text-align:left;">Đổi mật khẩu chủ động tại <code>/profile/security</code> bằng cách xác nhận Mật khẩu hiện tại + Mật khẩu mới (khác mật khẩu cũ <code>BR-08</code>) và thu hồi Refresh Token trên các thiết bị khác.</td></tr><tr><td style="text-align:center;"><strong><code>3.2.6</code></strong></td><td style="text-align:center;"><code>UC-006</code></td><td style="text-align:left;"><strong>OTP Verification</strong></td><td style="text-align:left;"><code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></td><td style="text-align:left;">Xác thực mã OTP 6 chữ số gửi qua email trên <code>/verify-otp</code> phục vụ kích hoạt tài khoản mới (<code>3.2.1</code>) hoặc đặt lại mật khẩu (<code>3.2.4</code>). Dùng 1 lần trong 10 phút (<code>BR-03</code>); sai quá 5 lần sẽ khóa mã và yêu cầu <code>Resend OTP</code> (cooldown 60 giây <code>BR-04</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.2.7</code></strong></td><td style="text-align:center;"><code>UC-007</code></td><td style="text-align:left;"><strong>Two-Factor Authentication (2FA, TOTP)</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></td><td style="text-align:left;">Thiết lập và xác thực bảo mật 2 lớp chuẩn RFC 6238 bằng ứng dụng Authenticator. Chỉ hiển thị mã QR và ô nhập mã TOTP 6 chữ số (chu kỳ 30 giây, lệch ±1 bước <code>BR-09</code>); <strong>đã lược bỏ hiển thị Secret Key dạng văn bản và Backup Codes</strong>.</td></tr><tr><td style="text-align:center;"><strong><code>3.2.8</code></strong></td><td style="text-align:center;"><code>UC-008</code></td><td style="text-align:left;"><strong>Logout</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></td><td style="text-align:left;">Đăng xuất phiên hiện tại: đưa RS256 Access Token và Refresh Token vào danh sách thu hồi trên Redis (<code>jwt:blacklist:{jti}</code>), xóa trạng thái nhạy cảm nhưng lưu lại gợi ý phương thức đăng nhập/không gian gần nhất (<code>BR-05</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.2.9</code></strong></td><td style="text-align:center;"><code>UC-009</code></td><td style="text-align:left;"><strong>Delete Account</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></td><td style="text-align:left;">Xóa mềm (<code>Soft Delete</code>) tài khoản cá nhân tại <code>/profile/security</code> kèm xác nhận mật khẩu. Kiểm tra không còn giữ quyền <code>Owner</code> duy nhất của Agency đang hoạt động hoặc giao dịch treo (<code>BR-10</code>), lưu vết xóa mềm 30 ngày (<code>BR-16</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.3.1</code></strong></td><td style="text-align:center;"><code>UC-010</code></td><td style="text-align:left;"><strong>View User Profile</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></td><td style="text-align:left;">Xem hồ sơ cá nhân tại <code>/profile</code>: Avatar, Họ tên, Email (chỉ đọc <code>BR-11</code>), Số điện thoại, Chức danh/Vai trò, Múi giờ, Ngôn ngữ giao diện (<code>VI</code>/<code>EN</code>), Ngày tham gia và trạng thái 2FA.</td></tr><tr><td style="text-align:center;"><strong><code>3.3.2</code></strong></td><td style="text-align:center;"><code>UC-011</code></td><td style="text-align:left;"><strong>Update User Profile</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code></td><td style="text-align:left;">Cập nhật Họ tên, Số điện thoại, Giới thiệu, Ngôn ngữ/Múi giờ và tải ảnh Avatar (<code>JPG</code>/<code>PNG</code>/<code>WEBP</code> ≤ 5 MB lên S3 <code>BR-12</code>); khóa cố định Email định danh (<code>BR-11</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.3.3</code></strong></td><td style="text-align:center;"><code>UC-012</code></td><td style="text-align:left;"><strong>View Client Profile</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Client</code></td><td style="text-align:left;">Xem hồ sơ thương hiệu độc lập của <code>Client</code> (<code>/client/profile</code>) có thể tái sử dụng xuyên suốt nhiều Agency và Workspace khác nhau mà không cần nhập lại (<code>BR-13</code>, <code>BR-14</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.3.4</code></strong></td><td style="text-align:center;"><code>UC-013</code></td><td style="text-align:left;"><strong>Update Client Profile</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Client</code></td><td style="text-align:left;">Cập nhật Tên thương hiệu, Logo, Ngành hàng, Website, Mã số thuế, Địa chỉ, Số điện thoại và Tông giọng thương hiệu (<code>/client/profile</code>); khóa không cho sửa Email định danh (<code>BR-14</code>) và tự động đồng bộ sang mọi Workspace liên kết (<code>BR-13</code>).</td></tr></tbody></table><hr><h2 id="_2-đac-ta-chi-tiet-nhom-3-2-authentication-authorization" tabindex="-1">2. Đặc tả Chi tiết Nhóm <code>3.2 Authentication &amp; Authorization</code> <a class="header-anchor" href="#_2-đac-ta-chi-tiet-nhom-3-2-authentication-authorization" aria-label="Permalink to &quot;2. Đặc tả Chi tiết Nhóm `3.2 Authentication &amp; Authorization`&quot;">​</a></h2><h3 id="_2-1-đang-ky-xac-thuc-otp-3-2-1-sign-up-3-2-6-otp-verification" tabindex="-1">2.1. Đăng ký &amp; Xác thực OTP (<code>3.2.1 Sign Up</code> &amp; <code>3.2.6 OTP Verification</code>) <a class="header-anchor" href="#_2-1-đang-ky-xac-thuc-otp-3-2-1-sign-up-3-2-6-otp-verification" aria-label="Permalink to &quot;2.1. Đăng ký &amp; Xác thực OTP (`3.2.1 Sign Up` &amp; `3.2.6 OTP Verification`)&quot;">​</a></h3><ul><li><strong>Chuẩn hóa định danh (<code>BR-01</code>)</strong>: Địa chỉ email luôn được chuẩn hóa về chữ thường (<code>lowercase</code>) trước khi kiểm tra trùng lặp và lưu trữ.</li><li><strong>Chính sách mật khẩu (<code>BR-02</code>)</strong>: Tối thiểu 8 ký tự, chứa ít nhất 1 chữ số và băm một chiều bằng <code>BCrypt</code>.</li><li><strong>Cơ chế OTP (<code>BR-03</code>, <code>BR-04</code>)</strong>: Mã 6 chữ số có TTL 10 phút trên Redis; nếu nhập sai liên tiếp quá 5 lần thì vô hiệu hóa mã hiện hành và bắt buộc bấm <code>Resend OTP</code> (chờ cooldown 60 giây).</li></ul><h3 id="_2-2-đang-nhap-đa-phuong-thuc-2fa-3-2-2-3-2-3-3-2-7" tabindex="-1">2.2. Đăng nhập Đa phương thức &amp; 2FA (<code>3.2.2</code>, <code>3.2.3</code>, <code>3.2.7</code>) <a class="header-anchor" href="#_2-2-đang-nhap-đa-phuong-thuc-2fa-3-2-2-3-2-3-3-2-7" aria-label="Permalink to &quot;2.2. Đăng nhập Đa phương thức &amp; 2FA (`3.2.2`, `3.2.3`, `3.2.7`)&quot;">​</a></h3><ul><li><strong>Email/Password (<code>3.2.2 Sign In with Email</code>)</strong> và <strong>Google OAuth 2.0 (<code>3.2.3 Sign In with Google OAuth</code>)</strong> dùng chung cơ chế phát hành cặp khóa bất đối xứng <strong>RS256 JWT</strong> (<code>Access Token</code> 15 phút + <code>Refresh Token</code> 30 ngày trong HttpOnly cookie — xem <a href="./../api/rs256-jwt-flow.html">RS256 JWT Flow</a>).</li><li><strong>2FA TOTP (<code>3.2.7</code>)</strong>: Thiết kế tối giản bề mặt tấn công — chỉ quét QR bằng Google/Microsoft Authenticator và xác nhận mã 6 số, không phơi bày chuỗi khóa bí mật thô hay mã dự phòng tĩnh.</li></ul><h3 id="_2-3-khoi-phuc-đoi-mat-khau-đang-xuat-xoa-mem-tai-khoan-3-2-4-3-2-5-3-2-8-3-2-9" tabindex="-1">2.3. Khôi phục / Đổi mật khẩu, Đăng xuất &amp; Xóa mềm tài khoản (<code>3.2.4</code>, <code>3.2.5</code>, <code>3.2.8</code>, <code>3.2.9</code>) <a class="header-anchor" href="#_2-3-khoi-phuc-đoi-mat-khau-đang-xuat-xoa-mem-tai-khoan-3-2-4-3-2-5-3-2-8-3-2-9" aria-label="Permalink to &quot;2.3. Khôi phục / Đổi mật khẩu, Đăng xuất &amp; Xóa mềm tài khoản (`3.2.4`, `3.2.5`, `3.2.8`, `3.2.9`)&quot;">​</a></h3><ul><li>Khi hoàn tất <code>3.2.4 Reset Password</code> hoặc <code>3.2.5 Change Password</code>, hệ thống lập tức thu hồi các phiên đăng nhập cũ để bảo vệ tài khoản (<code>BR-08</code>).</li><li>Khi thực hiện <code>3.2.9 Delete Account</code>, hệ thống kiểm tra ràng buộc <code>BR-10</code> (không còn là <code>Owner</code> duy nhất của Agency đang hoạt động hoặc còn giao dịch thanh toán treo), chuyển tài khoản sang <code>DELETED</code> (giữ thời gian ân hạn khôi phục 30 ngày <code>BR-16</code>) và thu hồi toàn bộ token trên Redis.</li></ul><hr><h2 id="_3-đac-ta-chi-tiet-nhom-3-3-user-client-profile" tabindex="-1">3. Đặc tả Chi tiết Nhóm <code>3.3 User &amp; Client Profile</code> <a class="header-anchor" href="#_3-đac-ta-chi-tiet-nhom-3-3-user-client-profile" aria-label="Permalink to &quot;3. Đặc tả Chi tiết Nhóm `3.3 User &amp; Client Profile`&quot;">​</a></h2><h3 id="_3-1-ho-so-ca-nhan-3-3-1-view-user-profile-3-3-2-update-user-profile" tabindex="-1">3.1. Hồ sơ Cá nhân (<code>3.3.1 View User Profile</code> &amp; <code>3.3.2 Update User Profile</code>) <a class="header-anchor" href="#_3-1-ho-so-ca-nhan-3-3-1-view-user-profile-3-3-2-update-user-profile" aria-label="Permalink to &quot;3.1. Hồ sơ Cá nhân (`3.3.1 View User Profile` &amp; `3.3.2 Update User Profile`)&quot;">​</a></h3><ul><li>Lưu trữ thông tin định danh cá nhân, ảnh đại diện S3 (<code>≤ 5 MB</code>) và ngôn ngữ làm việc (<code>vi</code> / <code>en</code>) quyết định ngôn ngữ giao diện cũng như ngôn ngữ các email thông báo gửi tới người dùng. Trường Email đăng nhập luôn chỉ-đọc (<code>BR-11</code>).</li></ul><h3 id="_3-2-ho-so-thuong-hieu-khach-hang-tai-su-dung-3-3-3-view-client-profile-3-3-4-update-client-profile" tabindex="-1">3.2. Hồ sơ Thương hiệu Khách hàng Tái sử dụng (<code>3.3.3 View Client Profile</code> &amp; <code>3.3.4 Update Client Profile</code>) <a class="header-anchor" href="#_3-2-ho-so-thuong-hieu-khach-hang-tai-su-dung-3-3-3-view-client-profile-3-3-4-update-client-profile" aria-label="Permalink to &quot;3.2. Hồ sơ Thương hiệu Khách hàng Tái sử dụng (`3.3.3 View Client Profile` &amp; `3.3.4 Update Client Profile`)&quot;">​</a></h3><ul><li>Tách bảng <code>client_profiles</code> độc lập khỏi <code>users</code> (xem <a href="./../database/schema/database-strategy.html">Database Strategy V2</a>): một tài khoản <code>Client</code> duy trì một hồ sơ thương hiệu thống nhất (Logo, Tên thương hiệu, Mã số thuế, Ngành hàng, Tông giọng) tái sử dụng xuyên nhiều Agency/Workspace (<code>BR-13</code>), với địa chỉ email định danh cố định không thay đổi (<code>BR-14</code>).</li><li>Logo và tên thương hiệu trong <code>Client Profile</code> đồng thời được dùng khi đóng dấu Watermark (<code>3.6.18</code>), xuất bản đề xuất/báo cáo PDF và làm tên hiển thị người gửi bản tin Newsletter.</li></ul><hr><h2 id="_4-danh-muc-quy-tac-nghiep-vu-ap-dung-br-01-–-br-14-br-16" tabindex="-1">4. Danh mục Quy tắc Nghiệp vụ Áp dụng (<code>BR-01</code> – <code>BR-14</code>, <code>BR-16</code>) <a class="header-anchor" href="#_4-danh-muc-quy-tac-nghiep-vu-ap-dung-br-01-–-br-14-br-16" aria-label="Permalink to &quot;4. Danh mục Quy tắc Nghiệp vụ Áp dụng (`BR-01` – `BR-14`, `BR-16`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Mã BR</th><th style="text-align:left;">Tên Quy tắc</th><th style="text-align:left;">Quy định Ràng buộc Cụ thể</th><th style="text-align:left;">FR Áp dụng</th></tr></thead><tbody><tr><td style="text-align:center;"><code>BR-01</code></td><td style="text-align:left;"><strong>Chuẩn hóa &amp; Duy nhất Email</strong></td><td style="text-align:left;">Email đăng ký luôn được cắt khoảng trắng và chuyển về chữ thường (<code>lowercase</code>); mỗi địa chỉ email chỉ gắn với tối đa 01 tài khoản <code>users</code> duy nhất.</td><td style="text-align:left;"><code>3.2.1</code>, <code>3.2.2</code>, <code>3.10.7</code></td></tr><tr><td style="text-align:center;"><code>BR-02</code></td><td style="text-align:left;"><strong>Độ mạnh Mật khẩu &amp; Băm</strong></td><td style="text-align:left;">Mật khẩu bắt buộc dài tối thiểu 8 ký tự, chứa ít nhất 1 chữ số và lưu trữ dưới dạng băm một chiều <code>BCrypt</code> (cost factor ≥ 10).</td><td style="text-align:left;"><code>3.2.1</code>, <code>3.2.4</code>, <code>3.2.5</code></td></tr><tr><td style="text-align:center;"><code>BR-03</code></td><td style="text-align:left;"><strong>Thời hạn Mã OTP</strong></td><td style="text-align:left;">Mã OTP gồm 6 chữ số ngẫu nhiên, chỉ sử dụng đúng 01 lần trong thời hạn hiệu lực tối đa <strong>10 phút</strong> kể từ thời điểm cấp phát.</td><td style="text-align:left;"><code>3.2.1</code>, <code>3.2.4</code>, <code>3.2.6</code></td></tr><tr><td style="text-align:center;"><code>BR-04</code></td><td style="text-align:left;"><strong>Chống Brute-force &amp; Cooldown OTP</strong></td><td style="text-align:left;">Nhập sai OTP liên tiếp quá <strong>5 lần</strong> sẽ hủy hiệu lực mã hiện tại; yêu cầu gửi lại (<code>Resend OTP</code>) phải chờ tối thiểu <strong>60 giây</strong>.</td><td style="text-align:left;"><code>3.2.4</code>, <code>3.2.6</code></td></tr><tr><td style="text-align:center;"><code>BR-05</code></td><td style="text-align:left;"><strong>Trạng thái Tài khoản Đăng nhập</strong></td><td style="text-align:left;">Chỉ tài khoản ở trạng thái <code>ACTIVE</code> mới được cấp phiên làm việc; tài khoản <code>PENDING_VERIFICATION</code> chuyển sang xác thực OTP, còn <code>SUSPENDED</code>/<code>BANNED</code>/<code>INACTIVE</code> bị từ chối ngay tại bước xác thực.</td><td style="text-align:left;"><code>3.2.2</code>, <code>3.2.3</code>, <code>3.2.8</code></td></tr><tr><td style="text-align:center;"><code>BR-06</code></td><td style="text-align:left;"><strong>Cặp Khóa RS256 &amp; Tách Quyền Gateway</strong></td><td style="text-align:left;"><code>brandhub-business-service</code> giữ khóa riêng tư RSA để ký <code>Access Token</code> (<code>15 phút</code>) + <code>Refresh Token</code> (<code>30 ngày</code>); <code>brandhub-api-gateway</code> chỉ giữ khóa công khai để xác minh chữ ký và đối chiếu danh sách thu hồi <code>jwt:blacklist:{jti}</code> trên Redis.</td><td style="text-align:left;"><code>3.2.2</code>, <code>3.2.3</code>, <code>3.2.8</code></td></tr><tr><td style="text-align:center;"><code>BR-07</code></td><td style="text-align:left;"><strong>Liên kết Tự động Google OAuth</strong></td><td style="text-align:left;">Khi đăng nhập Google OAuth với <code>email_verified = true</code>, nếu email đã tồn tại ở trạng thái hợp lệ thì tự động liên kết bản ghi <code>user_oauth_providers</code>; nếu chưa có thì khởi tạo tài khoản <code>ACTIVE</code>.</td><td style="text-align:left;"><code>3.2.3</code></td></tr><tr><td style="text-align:center;"><code>BR-08</code></td><td style="text-align:left;"><strong>Thu hồi Phiên khi Đổi Mật khẩu</strong></td><td style="text-align:left;">Mật khẩu mới không được trùng mật khẩu hiện hành; ngay khi đổi hoặc đặt lại mật khẩu thành công, toàn bộ <code>user_refresh_tokens</code> cũ của tài khoản bị thu hồi.</td><td style="text-align:left;"><code>3.2.4</code>, <code>3.2.5</code></td></tr><tr><td style="text-align:center;"><code>BR-09</code></td><td style="text-align:left;"><strong>Chuẩn TOTP RFC 6238</strong></td><td style="text-align:left;">Mã bảo mật 2 lớp TOTP 6 chữ số có chu kỳ xoay vòng 30 giây (cho phép độ lệch đồng hồ <code>±1</code> bước); không hiển thị chuỗi khóa gốc dạng văn bản hay mã dự phòng tĩnh.</td><td style="text-align:left;"><code>3.2.7</code></td></tr><tr><td style="text-align:center;"><code>BR-10</code></td><td style="text-align:left;"><strong>Điều kiện Tiên quyết Xóa Tài khoản</strong></td><td style="text-align:left;">Không cho phép xóa tài khoản nếu người dùng vẫn đang là <code>Owner</code> duy nhất của một <code>Agency</code> hoạt động có thành viên/dữ liệu chung hoặc còn giao dịch thanh toán treo <code>PENDING</code>.</td><td style="text-align:left;"><code>3.2.9</code></td></tr><tr><td style="text-align:center;"><code>BR-11</code></td><td style="text-align:left;"><strong>Khóa Cố định Email Cá nhân</strong></td><td style="text-align:left;">Trường <code>users.email</code> là định danh gốc chỉ-đọc trên màn hình hồ sơ cá nhân và trang quản trị.</td><td style="text-align:left;"><code>3.3.1</code>, <code>3.3.2</code>, <code>3.10.8</code></td></tr><tr><td style="text-align:center;"><code>BR-12</code></td><td style="text-align:left;"><strong>Giới hạn Tệp Ảnh Đại diện &amp; Đính kèm</strong></td><td style="text-align:left;">Ảnh Avatar / Logo tải lên S3 chỉ chấp nhận định dạng ảnh hợp lệ (<code>JPG</code>, <code>PNG</code>, <code>WEBP</code>) với dung lượng tối đa <code>5 MB</code>.</td><td style="text-align:left;"><code>3.3.2</code>, <code>3.3.4</code>, <code>3.4.5</code></td></tr><tr><td style="text-align:center;"><code>BR-13</code></td><td style="text-align:left;"><strong>Tái sử dụng Hồ sơ <code>Client</code> Đa Agency</strong></td><td style="text-align:left;">Một bản ghi <code>client_profiles</code> độc lập có thể liên kết đồng thời vào nhiều <code>Workspace</code> thuộc nhiều <code>Agency</code> khác nhau; cập nhật hồ sơ thương hiệu tự động phản ánh trên toàn bộ không gian liên kết.</td><td style="text-align:left;"><code>3.3.3</code>, <code>3.3.4</code></td></tr><tr><td style="text-align:center;"><code>BR-14</code></td><td style="text-align:left;"><strong>Bất biến Email Hồ sơ Thương hiệu</strong></td><td style="text-align:left;">Địa chỉ email định danh trên <code>client_profiles</code> được khóa cố định sau khi khởi tạo để bảo toàn liên kết mời khách hàng xuyên hệ thống.</td><td style="text-align:left;"><code>3.3.3</code>, <code>3.3.4</code></td></tr><tr><td style="text-align:center;"><code>BR-16</code></td><td style="text-align:left;"><strong>Ân hạn Xóa Mềm 30 Ngày</strong></td><td style="text-align:left;">Tài khoản cá nhân xóa mềm (<code>3.2.9</code>) được bảo lưu trạng thái 30 ngày trước khi hết hạn khôi phục.</td><td style="text-align:left;"><code>3.2.9</code>, <code>3.4.6</code>, <code>3.4.17</code></td></tr></tbody></table><hr><h2 id="_5-so-đo-luong-xac-thuc-đinh-tuyen-sau-đang-nhap" tabindex="-1">5. Sơ đồ Luồng Xác thực &amp; Định tuyến Sau Đăng nhập <a class="header-anchor" href="#_5-so-đo-luong-xac-thuc-đinh-tuyen-sau-đang-nhap" aria-label="Permalink to &quot;5. Sơ đồ Luồng Xác thực &amp; Định tuyến Sau Đăng nhập&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    G[&quot;Guest (/login, /register)&quot;] --&gt; AUTH{&quot;Sign In / Google OAuth&lt;br/&gt;(3.2.1 – 3.2.3)&quot;}</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    AUTH --&gt;|&quot;PENDING_VERIFICATION&quot;| OTP[&quot;Verify 6-digit OTP&lt;br/&gt;(3.2.6)&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    AUTH --&gt;|&quot;2FA Enabled&quot;| TOTP[&quot;Verify TOTP QR Code&lt;br/&gt;(3.2.7)&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    OTP --&gt; ISSUE[&quot;Issue RS256 JWT + Refresh Cookie&lt;br/&gt;(business-service)&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    TOTP --&gt; ISSUE</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    AUTH --&gt;|&quot;Direct Active&quot;| ISSUE</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ISSUE --&gt;|&quot;SystemRole = ADMIN&quot;| ADM[&quot;/admin/dashboard&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ISSUE --&gt;|&quot;Client-only invite&quot;| PRT[&quot;/workspaces/:id/portal&quot;]</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ISSUE --&gt;|&quot;Owner / Manager / Creator&quot;| AGY[&quot;/agencies (or Personal Studio)&quot;]</span></span></code></pre></div><hr><h2 id="_6-anh-xa-thuc-the-co-so-du-lieu-dich-vu-thuc-thi" tabindex="-1">6. Ánh xạ Thực thể Cơ sở Dữ liệu &amp; Dịch vụ Thực thi <a class="header-anchor" href="#_6-anh-xa-thuc-the-co-so-du-lieu-dich-vu-thuc-thi" aria-label="Permalink to &quot;6. Ánh xạ Thực thể Cơ sở Dữ liệu &amp; Dịch vụ Thực thi&quot;">​</a></h2><ul><li><strong>PostgreSQL (<code>brandhub-business-service</code>)</strong>: <code>users</code>, <code>user_oauth_providers</code>, <code>user_refresh_tokens</code>, <code>user_system_roles</code>, <code>account_activation_tokens</code>, <code>client_profiles</code>, <code>audit_logs</code>.</li><li><strong>Redis (<code>brandhub-api-gateway</code> &amp; <code>brandhub-business-service</code>)</strong>: <code>jwt:blacklist:{jti}</code> (<code>TTL ≤ 15m</code>), <code>oauth:state:{state}</code> (<code>TTL 10m</code>), bộ nhớ đệm OTP &amp; bộ đếm giới hạn sai <code>BR-04</code>.</li></ul>',28)])])}const p=e(d,[["render",i]]);export{u as __pageData,p as default};
